window.RP_SESSION={"id":"S-19144d288461","messages":[{"id":"RP-III-0186115","time":"2026-09-22T22:49:00+09:00","room":"RP III","name":"헥터","profile":"헥터","identity":"reviewed","type":"dialogue","body":"첫 사람의 죽음.\n그에게 처음 사람이 죽는것을 지켜본것은 9살때의 일이었다.\n.\n그의 할아버지는 그가 9살이 될무렵 넘어지셔 앓아 누우셨다.\n그것이 이미 앓던 상태로 넘어지신건지 넘어지셔서 앓게된건지는\n그렇게까지 기억이 정확하지 않아 아직까지도 자세히 알 정황이 없었다.\n그의 부모님에게 그 일을 물어보고 싶지도 않았기에.\n.\n여튼 그가 9살이 되고 또 7달이 지나자 할아버지의 병세가 급격하게 나빠지기 시작하였다.\n.\n그는 밖에서 놀다 그 소식을 듣고선 부리나케 집으로 달려가기 시작했다.\n\n그렇게 도착한 집 앞의 문에는 노란 나비 한마리가 서성였는데 그는 그것이 마치 신의 사자가 할아버지를 데리러 온것 같아 그 나비를 밟아버렸다.\n그가 의도한 첫 죽음이었다.\n.\n그러고서 그는 집안으로 들어가 할아버지의 손을 붙잡고서 기도하였다.\n자신의 생명을 그의 할아버지에게 옮겨달라고.\n지금 생각해보면 참으로 아이러니하였다.\n.\n.\n기적이었을까 그의 할아버지는 일주일간 편안한 상태로 침대에 누워계셨","characters":["P-26967fcb5ca6"]},{"id":"RP-III-0186116","time":"2026-09-22T22:49:00+09:00","room":"RP III","name":"헥터","profile":"헥터","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-26967fcb5ca6"]},{"id":"RP-III-0186117","time":"2026-09-22T22:49:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
